import {TABS,SORTS,clone,normalizeCatalog,initialConfig,poolFor,resolveList,filterList,reorder,togglePin,autoArrange,composeFeed,validateConfig,validDetail,removeStarterBanners,MATERIALS,migrateSavedConfig,swipeThresholds,swipeIntent,TAG_GROUPS,emptyDiscovery,hasDiscovery,discoverProducts} from './model.js?v=8';

const app=document.getElementById('app'),overlay=document.getElementById('overlay-root');
const KEYS={published:'pr-studio-published-v1',draft:'pr-studio-draft-v1',history:'pr-studio-history-v1',favorites:'pr-studio-favorites-v1',cart:'pr-studio-cart-v1'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>Number(n).toLocaleString('ko-KR')+'원';
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',up:'<path d="m5 15 7-7 7 7"/>',down:'<path d="m5 9 7 7 7-7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',banner:'<rect x="3" y="4" width="18" height="16" rx="1"/><circle cx="8" cy="9" r="1"/><path d="m3 17 5-5 4 4 4-5 5 5"/>',history:'<path d="M3 11a9 9 0 1 1 2 6M3 4v7h7M12 7v5l4 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',pin:'<path d="m8 3 8 0-1 6 4 4H5l4-4-1-6Zm4 10v8"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',save:'<path d="M4 3h13l3 3v15H4V3Z"/><path d="M8 3v6h8V3M8 21v-7h8v7"/>',home:'<path d="m3 10 9-8 9 8v11h-7v-7h-4v7H3V10Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
let catalog=[],published,draft,history=[],favorites=[],cart=[],dirty=false,view='shop',adminPage='list',adminTab='추천',adminQuery='',adminLimit=60,selected=new Set(),tab='추천',previewMode=false,frameMode=false,observer,photoState=new Map(),lastFocus=null;
const tabStates=Object.fromEntries(TABS.map(t=>[t,{query:'',material:'전체',sort:'curated',limit:8,scroll:0,favoritesOnly:false,discovery:emptyDiscovery()}]));
let toastTimer, feedRevision=0,photoReadToken=0,discoveryOpen=false;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('브라우저 저장 공간이 부족합니다. 작은 이미지를 쓰거나 구성 파일을 내보내세요.');return false;}}
function markDirty(){dirty=JSON.stringify(draft)!==JSON.stringify(published);}
function loadConfig(key,fallback){try{return migrateSavedConfig(read(key,fallback),catalog);}catch{return clone(fallback);}}
function currentConfig(){return previewMode?draft:published;}
function labbar(){return frameMode?'':`<div class="labbar"><div class="lab-title"><i class="signal"></i><span>INTERACTIVE PROTOTYPE</span><span class="subtext">/ 상품 ${catalog.length.toLocaleString('ko-KR')}개 · 10/13 수집본</span></div><div class="lab-actions"><button data-action="view-shop" class="${view==='shop'?'active':''}">고객 화면</button><button data-action="view-admin" class="${view==='admin'?'active':''}">운영자 화면</button><button data-action="open-guide" class="help-btn" aria-label="목업 안내">${icon('info')}</button></div></div>`;}
function render(){const filterScroll=app.querySelector('.discovery-body')?.scrollTop||0;const focus=document.activeElement;const focusTag=focus?.dataset.group?{group:focus.dataset.group,tag:focus.dataset.tag}:null;app.classList.toggle('shop-view',view==='shop');observer?.disconnect();app.innerHTML=labbar()+(view==='admin'?adminHTML():shopHTML());if(view==='shop')renderFeed();else if(adminPage==='list')renderAdminRows();bindDrag();syncFilterSheet();const sheet=app.querySelector('.discovery-body');if(sheet)sheet.scrollTop=filterScroll;if(discoveryOpen&&focusTag)app.querySelector(`[data-group="${focusTag.group}"][data-tag="${CSS.escape(focusTag.tag)}"]`)?.focus({preventScroll:true});}
function shopHTML(){const s=tabStates[tab];return `${previewMode?'<div class="preview-ribbon">편집 중인 초안 미리보기'+(frameMode?'':'<button data-action="return-admin">편집으로 돌아가기</button>')+'</div>':''}
<header class="shop-header"><div class="header-main"><button class="wordmark" data-action="home" aria-label="핑크로켓 홈"><picture><source media="(max-width: 60rem)" srcset="./assets/skin/logo-mobile.png"><img src="./assets/skin/logo-pc.png" alt="PINKROCKET" draggable="false"></picture></button><div class="catalog-search"><div class="searchbox">${icon('search')}<label class="sr-only" for="shop-search">상품 검색</label><input type="search" id="shop-search" aria-label="상품 검색" placeholder="상품 검색" value="${esc(s.query)}"><button data-action="open-filters" aria-label="사진 색감과 태그로 찾기">${icon('grid')}</button></div></div><div class="header-icons"><button class="text-button wish-trigger ${s.favoritesOnly?'active':''}" data-action="toggle-favorites" aria-label="찜한 상품 보기">${icon('heart')}${favorites.length?'<span class="wish-count">'+favorites.length+'</span>':''}</button><button class="text-button cart-trigger" data-action="open-cart" aria-label="데모 장바구니 열기">${icon('bag')}${cart.length?'<span class="cart-count">'+cart.reduce((n,x)=>n+x.quantity,0)+'</span>':''}</button></div></div><nav class="category-tabs" aria-label="상품 카테고리" data-tab-swipe>${TABS.map(t=>`<button data-action="tab" data-tab="${t}" aria-current="${t===tab?'page':'false'}" class="${t===tab?'active':''}">${({반지:'반지·토우링',팔찌:'팔찌·발찌'})[t]||t}</button>`).join('')}</nav></header>
<main id="main-content" class="shop-main"><div class="catalog-heading" data-tab-swipe><div><h1>${s.favoritesOnly?'관심상품':tab==='추천'?'추천 상품':tab==='신상'?'신상품':esc(tab)}</h1><p id="category-description">${s.favoritesOnly?'찜한 상품':tab==='추천'?'추천 상품':tab==='신상'?'신상품':esc(tab)+' 상품'}</p></div><div class="tab-step"><button data-action="previous-tab" aria-label="이전 카테고리" ${TABS.indexOf(tab)===0?'disabled':''}>${icon('left')}</button><span>${TABS.indexOf(tab)+1} / ${TABS.length}</span><button data-action="next-tab" aria-label="다음 카테고리" ${TABS.indexOf(tab)===TABS.length-1?'disabled':''}>${icon('right')}</button></div></div>
<div class="browse-tools">${discoveryHTML(s)}<div class="filter-chips" aria-label="소재 필터">${MATERIALS.map(m=>`<button class="chip ${m===s.material?'active':''}" data-action="material" data-material="${m}" aria-pressed="${m===s.material}">${m==='전체'?'모든 소재':m}</button>`).join('')}</div></div><div class="filter-bar"><span id="result-count" class="result-count" aria-live="polite"></span><label class="sort-label"><span class="sr-only">상품 정렬</span><select id="shop-sort" class="sort-select" aria-label="상품 정렬">${Object.entries({curated:'추천순',match:'태그 추천순',newest:'신상품순 · 시연',priceAsc:'낮은 가격순',priceDesc:'높은 가격순'}).map(([value,label])=>`<option value="${value}" ${s.sort===value?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="catalog-grid"><div id="product-feed" class="feed" aria-label="${esc(tab)} 상품 목록" data-tab-swipe></div></div><div id="more-wrap" class="more-wrap"></div></main>
<footer class="shop-footer"><div><img class="footer-logo" src="./assets/skin/logo-pc.png" alt="PINKROCKET"><p>CS Center<br><a href="https://pf.kakao.com/_lxgBed/friend" target="_blank" rel="noopener">핑크로켓 카카오톡 ↗</a></p></div><div><p>인터랙티브 목업 · 상품 정보는 조회 시점의 사본입니다.<br>찜·장바구니는 이 브라우저의 데모이며 실제 주문에 반영되지 않습니다.</p><button data-action="view-admin" style="margin-top:.7rem;text-decoration:underline">메인 운영자 화면</button></div></footer><nav class="bottom-nav" aria-label="빠른 메뉴"><button data-action="home" class="${tab==='추천'&&!s.favoritesOnly?'active':''}">${icon('home')}<span>추천</span></button><button data-action="open-categories">${icon('grid')}<span>카테고리</span></button><button data-action="toggle-favorites" class="${s.favoritesOnly?'active':''}">${icon('heart')}<span>찜</span></button><button data-action="open-cart">${icon('bag')}<span>장바구니</span></button></nav>`;}
function visibleProducts(){const s=tabStates[tab];const base=filterList(resolveList(catalog,tab,currentConfig()),{...s,sort:'curated',favorites});return discoverProducts(base,s.discovery,{sort:s.sort});}
function discoveryHTML(s){const d=s.discovery;return `<details class="discovery" ${discoveryOpen?'open':''}><summary aria-label="상세 필터 열기">${icon('grid')}<span>필터</span><span id="discovery-summary"></span></summary><div class="filter-backdrop" data-action="close-filters"></div><div class="discovery-body" role="dialog" aria-modal="true" aria-label="상품 필터"><div class="filter-sheet-heading"><div><h2>상품 필터</h2></div><button data-action="close-filters" aria-label="필터 닫기">${icon('close')}</button></div>${TAG_GROUPS.map(g=>`<div class="tag-row"><h2>${g.label}</h2><div class="tag-options">${g.options.map(tag=>`<button data-action="discovery-tag" data-group="${g.key}" data-tag="${esc(tag)}" class="tag-option ${d.tags[g.key]?.includes(tag)?'selected':''}" aria-pressed="${!!d.tags[g.key]?.includes(tag)}">${esc(tag)}</button>`).join('')}</div></div>`).join('')}<div class="tag-row"><h2>가격 범위</h2><div class="price-inputs"><label><span class="sr-only">최저 가격</span><input id="discovery-min" type="number" min="0" inputmode="numeric" placeholder="최저 가격" value="${esc(d.min)}"></label><span>~</span><label><span class="sr-only">최고 가격</span><input id="discovery-max" type="number" min="0" inputmode="numeric" placeholder="최고 가격" value="${esc(d.max)}"></label><span>원</span>${[['5천 원 이하','5000'],['1만 원 이하','10000']].map(([label,max])=>`<button class="tag-option" data-action="price-preset" data-max="${max}">${label}</button>`).join('')}</div></div><div class="tag-row"><h2>사진 색감</h2><div class="photo-discovery"><label class="photo-upload">사진으로 비슷한 색 찾기<input id="discovery-photo" type="file" accept="image/*" aria-label="색감으로 찾을 사진 선택"></label>${d.photoPreview?`<img src="${esc(d.photoPreview)}" alt="선택한 색감 참고 사진"><button class="tag-option" data-action="clear-photo">사진 빼기 ×</button>`:''}<span>사진은 이 브라우저에서만 처리합니다.</span></div></div><div class="discovery-actions"><label><input type="checkbox" id="discovery-strict" ${d.strict?'checked':''}>선택한 태그가 일치하는 상품만</label><label>추천 범위 <select id="discovery-cap" aria-label="추천 상품 수">${[[0,'전체'],[500,'500개'],[1000,'1,000개']].map(([n,label])=>`<option value="${n}" ${d.cap===n?'selected':''}>${label}</option>`).join('')}</select></label><button class="tag-reset" data-action="reset-discovery">탐색 조건 초기화</button></div><p class="discovery-note">기본은 선택 조건과 가까운 순서입니다. 여러 태그를 고를 수 있고, 가격 범위는 목록에 적용됩니다. 사진 검색은 색감을 비교합니다.</p><div class="filter-apply"><button data-action="reset-discovery">초기화</button><button class="apply-filters" data-action="close-filters"><span id="filter-preview-count"></span> 상품 보기</button></div></div></details>`;}
function updateDiscoverySummary(){const d=tabStates[tab].discovery,el=app.querySelector('#discovery-summary');if(!el)return;const tags=TAG_GROUPS.flatMap(g=>d.tags[g.key]||[]);const count=tags.length+(d.min!==''||d.max!==''?1:0)+(d.photoTone?1:0);el.textContent=count||'';el.hidden=!count;el.title=[...tags,d.min!==''||d.max!==''?'가격 조건':'',d.photoTone?'사진 색감':''].filter(Boolean).join(' · ');}
function productHTML(p){const index=photoState.get(p.id)||0;return `<article class="product-card" data-product="${p.id}"><div class="product-photo" data-gallery="${p.id}"><button class="photo-link" data-action="quickview" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} 미리보기"><img src="${esc(p.images[index]||p.images[0]||'')}" alt="${esc(p.name)} 사진 ${index+1}" loading="lazy" decoding="async" draggable="false"></button><button class="photo-heart ${favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} ${favorites.includes(p.id)?'찜 취소':'찜 추가'}" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button>${p.images.length>1?`<button class="photo-arrow prev" data-action="slide" data-id="${p.id}" data-delta="-1" aria-label="이전 사진">${icon('left')}</button><button class="photo-arrow next" data-action="slide" data-id="${p.id}" data-delta="1" aria-label="다음 사진">${icon('right')}</button><span class="photo-counter">${index+1} / ${p.images.length}</span><span class="photo-dots">${p.images.map((_,i)=>`<i class="${i===index?'on':''}"></i>`).join('')}</span>`:'<span class="photo-counter">사진 1장</span>'}${p.soldout?'<span class="soldout">SOLD OUT</span>':''}</div><div class="product-meta"><button class="product-name" data-action="quickview" data-id="${p.id}">${esc(p.displayName||p.name)}</button><div class="product-bottom"><span class="price">${won(p.price)}</span><button class="quick-add" data-action="quickview" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} 옵션 미리보기">${icon('plus')}<span>미리보기</span></button></div></div></article>`;}
function bannerHTML(b){if(b.type==='notice')return `<aside class="feed-notice"><div><h3>${esc(b.title)}</h3><p>${esc(b.subtitle)}</p></div>${b.link?`<a href="${esc(b.link)}" target="_blank" rel="noopener" aria-label="${esc(b.title)} 자세히">${icon('arrow')}</a>`:'<span class="notice-symbol">✳</span>'}</aside>`;return `<aside class="feed-banner ${esc(['ink','blush','cream'].includes(b.tone)?b.tone:'cream')} ${b.span===2?'span-2':''} ${b.image?'has-image':''}">${b.image?`<img class="banner-image" src="${esc(b.image)}" alt="" loading="lazy">`:''}<span class="eyebrow">${esc(b.tag||'PINKROCKET EDIT')}</span><div><h3>${esc(b.title)}</h3><p>${esc(b.subtitle)}</p></div>${b.link?`<a class="banner-arrow" href="${esc(b.link)}" target="_blank" rel="noopener" aria-label="${esc(b.title)} 자세히">${icon('arrow')}</a>`:`<span class="banner-arrow">${icon('arrow')}</span>`}</aside>`;}
function renderFeed(){if(view!=='shop')return;const revision=++feedRevision;const list=visibleProducts(),s=tabStates[tab],feed=app.querySelector('#product-feed');let seen=0;const nodes=[];for(const block of composeFeed(list,currentConfig().banners,tab)){if(block.kind==='product'){if(seen>=s.limit)break;seen++;nodes.push(productHTML(block.data));}else nodes.push(bannerHTML(block.data));}feed.innerHTML=list.length?nodes.join(''):`<div class="empty"><h3>아직 이 조건에 맞는 상품이 없어요.</h3><p>${s.favoritesOnly?'찜한 상품이 없습니다.':'다른 소재를 선택하거나 검색어를 바꿔보세요.'}</p><button class="btn" data-action="clear-filters" style="margin-top:1rem">조건 초기화</button></div>`;app.querySelector('#result-count').textContent=`${list.length}개의 상품${s.favoritesOnly?' · 찜한 상품':''}`;app.querySelector('#more-wrap').innerHTML=seen<list.length?`<button class="more-btn" data-action="load-more">상품 더 보기 · ${seen} / ${list.length} ${icon('down')}</button><p class="end-copy">아래로 내려가면 다음 상품이 이어집니다.</p><div id="feed-sentinel" aria-hidden="true"></div>`:`<p class="end-copy">${list.length?'모든 상품을 확인했습니다.':''}</p>`;updateDiscoverySummary();const previewCount=app.querySelector('#filter-preview-count');if(previewCount)previewCount.textContent=list.length.toLocaleString('ko-KR')+'개';observer?.disconnect();const sentinel=app.querySelector('#feed-sentinel');if(sentinel&&'IntersectionObserver'in window){observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();setTimeout(()=>{if(view==='shop'&&revision===feedRevision){s.limit+=6;renderFeed();}},250);}},{rootMargin:'0px 0px 150px 0px'});observer.observe(sentinel);}updateURL();}
function updateURL(){if(frameMode)return;const s=tabStates[tab],url=new URL(location.href);url.searchParams.set('view',view);url.searchParams.set('tab',tab);for(const key of ['q','material','sort'])url.searchParams.delete(key);if(s.query)url.searchParams.set('q',s.query);if(s.material!=='전체')url.searchParams.set('material',s.material);if(s.sort!=='curated')url.searchParams.set('sort',s.sort);historyReplace(url);}
function historyReplace(url){try{window.history.replaceState(null,'',url);}catch{ /* Embedding may restrict history; local navigation must still work. */ }}
function setTab(next){if(!TABS.includes(next)||next===tab)return;tabStates[tab].scroll=window.scrollY;const navScroll=app.querySelector('.category-tabs')?.scrollLeft||0;tab=next;render();const nav=app.querySelector('.category-tabs');if(nav){nav.scrollLeft=navScroll;const active=nav.querySelector('.active');if(active&&nav.clientWidth&&active.offsetLeft+active.offsetWidth>nav.scrollLeft+nav.clientWidth)nav.scrollLeft=active.offsetLeft-nav.offsetLeft;if(active&&active.offsetLeft<nav.scrollLeft)nav.scrollLeft=active.offsetLeft-nav.offsetLeft;}requestAnimationFrame(()=>window.scrollTo({top:tabStates[next].scroll,behavior:'instant'}));}
function adjacentTab(delta){const next=TABS[TABS.indexOf(tab)+delta];if(next)setTab(next);}
function slide(id,delta){const p=catalog.find(p=>p.id===id);if(!p||p.images.length<2)return;photoState.set(id,((photoState.get(id)||0)+delta+p.images.length)%p.images.length);const card=app.querySelector(`[data-product="${CSS.escape(id)}"]`);if(card){const wrap=document.createElement('div');wrap.innerHTML=productHTML(p);card.replaceWith(wrap.firstElementChild);}}

function adminHTML(){return `<div class="studio-shell"><aside class="studio-sidebar"><div class="studio-logo">PINKROCKET<small>CURATION STUDIO</small></div><nav class="studio-nav" aria-label="운영자 메뉴">${[['list','진열 편집','grid'],['banners','배너·안내','banner'],['history','저장·공개 이력','history'],['guide','연결 구조','info']].map(([id,label,ico])=>`<button data-action="admin-page" data-page="${id}" class="${adminPage===id?'active':''}">${icon(ico)}${label}</button>`).join('')}</nav><div class="studio-sidebar-note">메인 진열 관리<br>상품 데이터: 메이크샵</div></aside><main id="main-content" class="studio-main"><div class="studio-heading"><div><div class="eyebrow">CURATION STUDIO / ${adminPage.toUpperCase()}</div><h1>${{list:'상품 진열',banners:'배너·안내',history:'저장·공개 이력',guide:'이용 안내'}[adminPage]}</h1><p>상품 순서·고정·제외·배너를 설정합니다.</p></div><div class="studio-toolbar"><span class="status-pill ${dirty?'dirty':''}">${dirty?'편집 중 · 미공개':'공개본과 동일'}</span>${button(icon('save')+'초안 저장','save-draft')}${button(icon('eye')+'미리보기','preview-draft')}${button('목업에 공개','publish','primary')}</div></div>${adminPage==='list'?adminListHTML():adminPage==='banners'?adminBannersHTML():adminPage==='history'?adminHistoryHTML():guideHTML()}</main></div>`;}
function adminListHTML(){const c=draft.tabs[adminTab],items=resolveList(catalog,adminTab,draft);return `<div class="studio-tabbar" aria-label="편집할 카테고리">${TABS.map(t=>`<button data-action="admin-tab" data-tab="${t}" class="${t===adminTab?'active':''}">${t}</button>`).join('')}</div><div class="studio-grid"><section class="panel"><div class="panel-header"><h2>${adminTab} 목록 <span style="color:var(--muted);font-weight:400">${items.length}개</span></h2><span class="eyebrow">DRAG · MOVE · PIN</span></div><div class="list-toolbar"><label class="list-search">${icon('search')}<input id="admin-search" type="search" value="${esc(adminQuery)}" placeholder="상품명 또는 ID 검색" aria-label="편집 목록 검색"></label><div class="row-actions">${button('선택 상단 고정','bulk-pin','small')}${button('선택 제외','bulk-exclude','small')}</div></div><div class="table-wrap"><table class="product-table"><thead><tr><th><input type="checkbox" data-select-all aria-label="표시 상품 전체 선택"></th><th>순서</th><th>상품 / 메이크샵 ID</th><th>가격</th><th>편집</th></tr></thead><tbody id="admin-rows"></tbody></table></div><div id="admin-more" class="admin-more"></div></section><aside class="studio-aside"><section class="panel side-card"><div class="panel-header"><h2>자동 진열 기준</h2></div><div class="panel-body"><label class="field"><span class="field-label">기본 정렬</span><select id="admin-sort" aria-label="운영자 기본 정렬">${Object.entries(SORTS).filter(([k])=>k!=='reviews'||catalog.some(p=>p.reviewCount)).map(([k,v])=>`<option value="${k}" ${c.sort===k?'selected':''}>${v}${k==='newest'?' · 시연':''}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" id="hide-soldout" ${c.hideSoldout?'checked':''} ${catalog.every(p=>p.stockStatus==='unknown')?'disabled':''}>품절 상품 숨기기 · 상태 수집 전</label>${button('정렬 기준 적용','apply-sort','accent full-btn')}<p style="margin-top:.6rem">상단 고정 · 수동 순서 · 제외 설정은 유지합니다. 수동 순서가 없으면 선택 기준으로 정렬됩니다.</p>${button('수동 순서 초기화 후 자동 정렬','reset-order','small full-btn','style="margin-top:.7rem"')}<div class="helper-box">상단 고정 상품이 먼저 표시됩니다. 나머지는 수동 순서 → 자동 정렬 순으로 채워집니다.</div></div></section><section class="panel side-card"><div class="panel-header"><h2>이 탭의 구성</h2></div><div class="panel-body"><div class="stat-row"><span>표시 상품</span><strong>${items.length}개</strong></div><div class="stat-row"><span>상단 고정</span><strong>${c.pins.length}개</strong></div><div class="stat-row"><span>수동 순서</span><strong>${c.manual.length?'설정됨':'자동'}</strong></div><div class="stat-row"><span>삽입 배너</span><strong>${draft.banners.filter(b=>b.enabled&&b.tabs.includes(adminTab)).length}개</strong></div></div></section><section class="panel side-card"><div class="panel-header"><h2>제외한 상품 ${c.excluded.length}</h2></div><div class="panel-body"><div class="excluded-list">${c.excluded.length?c.excluded.map(id=>{const p=catalog.find(p=>p.id===id);return `<button data-action="restore-product" data-id="${id}" aria-label="${esc(p?.name)} 제외 취소">${esc((p?.displayName||p?.name||id).slice(0,17))} ×</button>`;}).join(''):'<p>제외한 상품이 없습니다.</p>'}</div></div></section></aside></div>`;}
function renderAdminRows(){const list=resolveList(catalog,adminTab,draft),q=adminQuery.trim().toLowerCase(),exactId=list.some(p=>p.id===q),rows=list.filter(p=>exactId?p.id===q:!q||`${p.name} ${p.id}`.toLowerCase().includes(q)),positions=new Map(list.map((p,i)=>[p.id,i]));const body=app.querySelector('#admin-rows');if(!body)return;body.innerHTML=rows.length?rows.slice(0,adminLimit).map(p=>{const pos=positions.get(p.id);return `<tr draggable="true" data-row-id="${p.id}" class="${draft.tabs[adminTab].pins.includes(p.id)?'pinned':''}"><td><input type="checkbox" data-row-select="${p.id}" aria-label="${esc(p.displayName||p.name)} 선택" ${selected.has(p.id)?'checked':''}></td><td><input class="rank-input" type="number" min="1" max="${list.length}" value="${pos+1}" data-rank="${p.id}" aria-label="${esc(p.displayName||p.name)} 순번"></td><td><div class="table-product"><img src="${esc(p.images[0])}" alt="" loading="lazy"><div><div class="name">${esc(p.displayName||p.name)}</div><small>${p.id} · ${esc(p.material)}${draft.tabs[adminTab].pins.includes(p.id)?' · 상단 고정':''}</small></div></div></td><td>${won(p.price)}</td><td><div class="row-actions"><button data-action="pin" data-id="${p.id}" class="${draft.tabs[adminTab].pins.includes(p.id)?'on':''}" aria-label="${esc(p.displayName||p.name)} 상단 고정 전환" aria-pressed="${draft.tabs[adminTab].pins.includes(p.id)}">${icon('pin')}</button><button data-action="move-up" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} 위로 이동" ${pos===0?'disabled':''}>${icon('up')}</button><button data-action="move-down" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} 아래로 이동" ${pos===list.length-1?'disabled':''}>${icon('down')}</button><button data-action="exclude" data-id="${p.id}" aria-label="${esc(p.displayName||p.name)} 목록에서 제외">${icon('close')}</button></div></td></tr>`;}).join(''):'<tr><td colspan="5" style="padding:2rem;text-align:center">조건에 맞는 상품이 없습니다.</td></tr>';const more=app.querySelector('#admin-more');if(more)more.innerHTML=`<span>${Math.min(rows.length,adminLimit)} / ${rows.length}개 표시</span>${rows.length>adminLimit?button('다음 60개 표시','admin-more','small'):''}`;bindDrag();}
function adminBannersHTML(){return `<div class="studio-toolbar" style="margin-bottom:1rem">${button(icon('plus')+'배너·안내 추가','add-banner','primary')}<span class="result-count">상품 수를 기준으로 위치를 지정합니다. 상품 정렬과 배너 위치는 독립적입니다.</span></div><div class="banner-manager">${draft.banners.map(b=>`<section class="panel banner-edit-row"><div class="banner-swatch ${esc(b.tone)}">${esc(b.title)}</div><div class="banner-info"><h3>${esc(b.title)}</h3><p>${b.type==='notice'?'안내 띠배너':'기획 배너'} · ${b.after===0?'목록 맨 위':`상품 ${b.after}개 뒤`} · ${esc(b.tabs.join(' / '))}<br>${b.enabled?'노출 중':'숨김'}</p></div><div class="banner-actions">${button('편집','edit-banner','','data-id="'+esc(b.id)+'"')}${button(b.enabled?'숨기기':'노출하기','toggle-banner','','data-id="'+esc(b.id)+'"')}${button('복제','duplicate-banner','','data-id="'+esc(b.id)+'"')}${button('삭제','delete-banner','danger','data-id="'+esc(b.id)+'"')}</div></section>`).join('')}</div><div class="helper-box">실제 운영에서는 예약 노출·권한·이미지 저장소를 연결합니다. 이 목업에서는 노출 여부·탭·상품 뒤 위치·문구·이미지·링크를 직접 편집할 수 있습니다.</div>`;}
function adminHistoryHTML(){return `<div class="studio-toolbar" style="margin-bottom:1.2rem">${button('구성 JSON 내보내기','export-config')}${button('구성 JSON 가져오기','import-config')}${button('초안 불러오기','load-draft')}<input type="file" id="config-file" class="file-input" accept="application/json"></div><div class="history-list">${history.length?history.map(h=>`<section class="panel history-item"><div><h3>${esc(h.label)}</h3><p>${new Date(h.time).toLocaleString('ko-KR')} · ${h.type==='published'?'목업 공개본':'저장한 초안'}</p></div>${button('이 구성을 초안으로 복구','restore-history','','data-id="'+h.id+'"')}</section>`).join(''):'<section class="panel guide-step"><h2>아직 저장된 이력이 없습니다.</h2><p>초안을 저장하거나 목업에 공개하면 최근 8개의 구성이 여기에 남습니다.</p></section>'}</div>`;}
function guideHTML(){return `<div class="guide-grid">${[['01','상품은 메이크샵에서','대표님 공개 저장소의 상품 2,449개 중 이름·가격이 없는 70개를 제외한 2,379개를 사용합니다. 10/13 수집본이며 실시간 갱신은 연결 전입니다. 분류·소재 태그를 가져왔고 미분류 상품 38개는 전체 목록에서 확인할 수 있습니다.'],['02','탐색은 새로운 프론트에서','카테고리 탭, 소재 필터, 검색, 정렬, 상품 추가 표시와 3:4 카드 슬라이드를 체험합니다. 전체 수집본에서 상품을 이어서 표시합니다. 신상순은 등록일이 없는 시연 정렬입니다.'],['03','진열은 운영 스튜디오에서','자동 정렬과 별개로 순서를 옮기고, 상단에 고정하고, 상품을 제외할 수 있습니다. 배너는 상품 몇 개 뒤에 넣을지 지정합니다.'],['04','확인 후 목업에 공개','초안은 공개본과 분리됩니다. 미리보기로 확인한 뒤 목업에 공개하세요. 브라우저 저장만 사용하며 같은 브라우저의 탭 사이에 공유됩니다.'],['05','구매는 기존 상세로','상품 미리보기의 ‘메이크샵 상세 열기’로 실제 상세에 이동합니다. 이 사이트 안의 찜·장바구니는 데모이며 실제 메이크샵 계정에는 반영되지 않습니다.'],['06','브라우저 자동화에 맞게','상품 ID, 이름이 있는 버튼, 순번 입력과 일괄 동작을 제공합니다. 드래그 없이도 목록을 편집할 수 있습니다. 실제 운영에는 로그인·권한·공유 저장소를 연결해야 합니다.']].map(([n,t,p])=>`<section class="panel guide-step"><div class="num">${n}</div><h2>${t}</h2><p>${p}</p></section>`).join('')}</div>`;}

function openDrawer(title,html,wide=false){lastFocus=document.activeElement;overlay.innerHTML=`<div class="overlay-backdrop" data-dismiss><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-header"><h2>${esc(title)}</h2><button class="close-button" data-action="close" aria-label="닫기">${icon('close')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';overlay.querySelector('button,input,select,a,textarea')?.focus();}
function closeOverlay(){overlay.innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function openQuickview(id){const p=catalog.find(p=>p.id===id);if(!p)return;const index=photoState.get(id)||0;openDrawer('상품 정보',`<div class="quickview-photo"><img id="quickview-image" src="${esc(p.images[index]||p.images[0])}" alt="${esc(p.name)}"></div>${p.images.length>1?`<div class="gallery-thumbs">${p.images.map((src,i)=>`<button data-action="gallery-thumb" data-id="${id}" data-index="${i}" class="${i===index?'active':''}" aria-label="상품 사진 ${i+1}"><img src="${esc(src)}" alt=""></button>`).join('')}</div>`:'<p class="field-note">이 상품은 대표 사진 1장입니다.</p>'}<div class="eyebrow" style="margin-top:1rem">${esc(p.materials.join(' · '))} / ${esc(p.categories.join(' · '))}</div><h3 class="quickview-name">${esc(p.name)}</h3><p class="quickview-price">${won(p.price)}</p><p class="quickview-note">상품 ID ${id} · 조회 시점의 상품 정보입니다.<br>실제 옵션·현재 가격·품절 여부는 메이크샵 상세에서 확인하세요.</p><div class="demo-note">아래 수량 담기는 화면 흐름을 보여주는 데모입니다. 실제 주문이나 메이크샵 장바구니에는 반영되지 않습니다.</div><label class="field"><span class="field-label">데모 수량</span><input id="demo-quantity" type="number" value="1" min="1" max="99" aria-label="데모 수량"></label><div class="studio-toolbar">${button(icon('bag')+'데모 장바구니에 담기','demo-add','primary','data-id="'+id+'"')}<button class="btn" data-action="favorite" data-id="${id}">${icon('heart')}찜 전환</button>${p.detailUrl?`<a class="btn" href="${esc(p.detailUrl)}" target="_blank" rel="noopener">메이크샵 상세 열기 ↗</a>`:''}</div>`);}
function openCart(){openDrawer('장바구니 · 로컬 데모',`<div class="demo-note">이 브라우저의 목업 장바구니입니다. 실제 주문·결제는 연결하지 않았습니다.</div>${cart.length?cart.map(item=>{const p=catalog.find(p=>p.id===item.id);if(!p)return '';return `<div class="cart-item"><img src="${esc(p.images[0])}" alt=""><div class="cart-info"><p>${esc(p.displayName||p.name)}</p><p>${won(p.price)}</p><div class="quantity"><button data-action="cart-minus" data-id="${item.id}" aria-label="수량 줄이기">−</button><span>${item.quantity}</span><button data-action="cart-plus" data-id="${item.id}" aria-label="수량 늘리기">+</button><button data-action="cart-remove" data-id="${item.id}" aria-label="${esc(p.name)} 삭제">×</button></div></div></div>`;}).join('')+`<div class="cart-footer"><span>데모 합계</span><strong>${won(cart.reduce((sum,item)=>sum+(catalog.find(p=>p.id===item.id)?.price||0)*item.quantity,0))}</strong></div>`:'<div class="empty"><h3>아직 담은 상품이 없어요.</h3><p>상품 미리보기에서 데모로 담아보세요.</p></div>'}`);}
function bannerEditor(id){const b=draft.banners.find(b=>b.id===id)||{id:'banner-'+Date.now(),type:'editorial',title:'새 배너',subtitle:'',tag:'PINKROCKET EDIT',after:4,span:2,tabs:[adminTab],enabled:true,tone:'cream',image:'',link:''};openDrawer(id?'배너·안내 편집':'배너·안내 추가',`<form id="banner-form" data-banner-id="${esc(b.id)}"><label class="field"><span class="field-label">콘텐츠 유형</span><select name="type"><option value="editorial" ${b.type==='editorial'?'selected':''}>기획 배너</option><option value="notice" ${b.type==='notice'?'selected':''}>안내 띠배너</option></select></label><label class="field"><span class="field-label">제목</span><textarea name="title" required maxlength="160">${esc(b.title)}</textarea></label><label class="field"><span class="field-label">설명</span><textarea name="subtitle" maxlength="300">${esc(b.subtitle)}</textarea></label><label class="field"><span class="field-label">작은 라벨</span><input name="tag" maxlength="70" value="${esc(b.tag)}"></label><label class="field"><span class="field-label">삽입 위치 · 상품 몇 개 뒤</span><input name="after" type="number" min="0" max="500" required value="${b.after}"><span class="field-note">0이면 목록 맨 위. 해당 탭의 상품이 더 적으면 목록 끝에 표시합니다.</span></label><label class="field"><span class="field-label">배너 너비</span><select name="span"><option value="2" ${b.span===2?'selected':''}>상품 카드 2칸</option><option value="1" ${b.span===1?'selected':''}>상품 카드 1칸</option></select></label><label class="field"><span class="field-label">배경</span><select name="tone">${[['ink','잉크 블랙'],['cream','라이트 세이지'],['blush','뮤트 블러시']].map(([value,label])=>`<option value="${value}" ${b.tone===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field"><span class="field-label">이미지 주소 · 선택 사항</span><input name="image" value="${esc(b.image)}" placeholder="https://… 또는 업로드"><span class="field-note">PNG/JPEG/WebP, 최대 800KB. 업로드 이미지는 이 브라우저에만 저장됩니다.</span><input type="file" id="banner-image-file" accept="image/png,image/jpeg,image/webp" style="margin-top:.5rem"></label><label class="field"><span class="field-label">이동 링크 · 선택 사항</span><input name="link" type="url" value="${esc(b.link)}" placeholder="https://…"></label><div class="field"><span class="field-label">노출할 탭</span><div class="tab-checks">${TABS.map(t=>`<label class="check-label"><input type="checkbox" name="tabs" value="${t}" ${b.tabs.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><label class="check-label"><input type="checkbox" name="enabled" ${b.enabled?'checked':''}>노출하기</label><p class="field-note" style="margin-bottom:1rem">예약 노출은 실제 운영 연결 단계에서 추가합니다.</p><button class="btn primary full-btn" type="submit">배너 변경 적용</button></form>`,true);}
function record(label,type,config){history=[{id:String(Date.now()),time:new Date().toISOString(),label,type,config:clone(config)},...history].slice(0,8);write(KEYS.history,history);}
function saveDraft(){if(write(KEYS.draft,draft)){record('편집 중인 구성 저장','draft',draft);toast('초안을 저장했습니다. 공개본은 바뀌지 않았습니다.');render();}}
function publish(){try{const value=validateConfig(draft,catalog);if(write(KEYS.published,value)){published=clone(value);write(KEYS.draft,draft);record('목업 공개본 업데이트','published',published);dirty=false;toast('목업 고객 화면에 반영했습니다. 실제 메이크샵은 변경되지 않습니다.');render();}}catch(error){toast(error.message);}}
function previewDraft(){write(KEYS.draft,draft);lastFocus=document.activeElement;const url=new URL(location.href);url.search='?view=shop&preview=1&frame=1&tab='+encodeURIComponent(adminTab);overlay.innerHTML=`<section class="preview-modal" role="dialog" aria-modal="true" aria-label="편집 중인 화면 미리보기"><div class="preview-modal-bar"><span>초안 미리보기 · ${esc(adminTab)}</span><div class="studio-toolbar">${button('모바일 폭','preview-mobile','small')}${button('전체 폭','preview-full','small')}${button('닫기','close','small')}</div></div><iframe title="초안 고객 화면" src="${esc(url.href)}"></iframe></section>`;document.body.style.overflow='hidden';overlay.querySelector('button')?.focus();}
function mutate(fn,message){fn();markDirty();render();if(message)toast(message);}
function move(id,direction){const items=resolveList(catalog,adminTab,draft),index=items.findIndex(p=>p.id===id);if(index<0)return;mutate(()=>reorder(draft,catalog,adminTab,id,index+direction));}

async function action(target){const a=target.dataset.action,id=target.dataset.id;
  if(a==='close')return closeOverlay();
  if(a==='view-shop'||a==='home'){closeOverlay();view='shop';previewMode=false;if(a==='home'){tab='추천';tabStates[tab].favoritesOnly=false;}render();updateURL();return window.scrollTo(0,0);}
  if(a==='view-admin'||a==='return-admin'){tabStates[tab].scroll=scrollY;closeOverlay();view='admin';previewMode=false;render();updateURL();return window.scrollTo(0,0);}
  if(a==='open-guide')return openDrawer('이 목업에서 확인할 수 있는 것',`<div class="demo-note">실제 메이크샵에는 어떤 변경도 보내지 않습니다.</div>${guideHTML()}`,true);
  if(a==='tab'){closeOverlay();return setTab(target.dataset.tab);}
  if(a==='previous-tab'||a==='next-tab')return adjacentTab(a==='next-tab'?1:-1);
  if(a==='open-categories')return openDrawer('카테고리',`<nav class="category-drawer">${TABS.map(t=>`<button class="btn full-btn ${t===tab?'primary':''}" data-action="tab" data-tab="${t}">${t}</button>`).join('')}</nav>`);
  if(a==='discovery-tag'){const s=tabStates[tab],g=target.dataset.group,t=target.dataset.tag;if(!TAG_GROUPS.find(x=>x.key===g)?.options.includes(t))return;const old=s.discovery.tags[g]||[];s.discovery.tags[g]=old.includes(t)?old.filter(x=>x!==t):[...old,t];s.sort='match';s.limit=8;discoveryOpen=true;return render();}
  if(a==='price-preset'){const s=tabStates[tab];s.discovery.min='0';s.discovery.max=target.dataset.max;s.sort='match';s.limit=8;discoveryOpen=true;return render();}
  if(a==='reset-discovery'){photoReadToken++;tabStates[tab].discovery=emptyDiscovery();tabStates[tab].sort='curated';tabStates[tab].limit=8;return render();}
  if(a==='clear-photo'){photoReadToken++;const d=tabStates[tab].discovery;d.photoTone=null;d.photoPreview='';return render();}
  if(a==='material'){tabStates[tab].material=target.dataset.material;tabStates[tab].limit=8;return render();}
  if(a==='clear-filters'){photoReadToken++;Object.assign(tabStates[tab],{query:'',material:'전체',sort:'curated',favoritesOnly:false,limit:8,discovery:emptyDiscovery()});return render();}
  if(a==='focus-search'){app.querySelector('.shop-header')?.classList.add('search-open');app.querySelector('#shop-search')?.focus();return;}
  if(a==='focus-filters'||a==='open-filters'){setFiltersOpen(true);return;}
  if(a==='close-filters'){setFiltersOpen(false);return;}
  if(a==='toggle-favorites'){tabStates[tab].favoritesOnly=!tabStates[tab].favoritesOnly;tabStates[tab].limit=8;return render();}
  if(a==='favorite'){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write(KEYS.favorites,favorites);if(view==='shop')render();toast(favorites.includes(id)?'찜한 상품에 담았습니다. · 로컬 데모':'찜을 해제했습니다. · 로컬 데모');return;}
  if(a==='slide')return slide(id,Number(target.dataset.delta));
  if(a==='load-more'){tabStates[tab].limit+=6;return renderFeed();}
  if(a==='quickview')return openQuickview(id);
  if(a==='gallery-thumb'){const p=catalog.find(p=>p.id===id),i=Number(target.dataset.index);if(!p?.images[i])return;photoState.set(id,i);overlay.querySelector('#quickview-image').src=p.images[i];overlay.querySelectorAll('.gallery-thumbs button').forEach(b=>b.classList.toggle('active',b===target));return;}
  if(a==='open-cart')return openCart();
  if(a==='demo-add'){const quantity=Number(overlay.querySelector('#demo-quantity')?.value);if(!Number.isInteger(quantity)||quantity<1||quantity>99)return toast('수량은 1~99 사이로 입력하세요.');const item=cart.find(x=>x.id===id);if(item)item.quantity=Math.min(99,item.quantity+quantity);else cart.push({id,quantity});write(KEYS.cart,cart);closeOverlay();render();return toast('데모 장바구니에 담았습니다. 실제 주문에는 반영되지 않습니다.');}
  if(a?.startsWith('cart-')){const item=cart.find(x=>x.id===id);if(!item)return;if(a==='cart-remove')cart=cart.filter(x=>x.id!==id);else item.quantity=Math.max(1,Math.min(99,item.quantity+(a==='cart-plus'?1:-1)));write(KEYS.cart,cart);render();return openCart();}
  if(a==='admin-page'){adminPage=target.dataset.page;selected.clear();return render();}
  if(a==='admin-more'){adminLimit+=60;return renderAdminRows();}
  if(a==='admin-tab'){adminLimit=60;adminTab=target.dataset.tab;selected.clear();adminQuery='';return render();}
  if(a==='pin')return mutate(()=>togglePin(draft,adminTab,id),'상단 고정 설정을 바꿨습니다.');
  if(a==='move-up'||a==='move-down')return move(id,a==='move-up'?-1:1);
  if(a==='exclude')return mutate(()=>{draft.tabs[adminTab].excluded=[...new Set([...draft.tabs[adminTab].excluded,id])];selected.delete(id);},'목록에서 제외했습니다. 제외 목록에서 복구할 수 있습니다.');
  if(a==='restore-product')return mutate(()=>draft.tabs[adminTab].excluded=draft.tabs[adminTab].excluded.filter(x=>x!==id),'제외를 취소했습니다.');
  if(a==='bulk-pin'||a==='bulk-exclude'){if(!selected.size)return toast('먼저 상품을 선택하세요.');return mutate(()=>{const c=draft.tabs[adminTab];if(a==='bulk-pin')c.pins=[...new Set([...c.pins,...selected])];else c.excluded=[...new Set([...c.excluded,...selected])];selected.clear();},'선택한 상품에 적용했습니다.');}
  if(a==='apply-sort'||a==='reset-order'){const sort=app.querySelector('#admin-sort').value;return mutate(()=>autoArrange(draft,adminTab,sort,a==='reset-order'),a==='reset-order'?'상단 고정·제외는 유지하고 수동 순서를 초기화했습니다.':'정렬 기준을 적용했습니다. 수동 편집은 유지됩니다.');}
  if(a==='save-draft')return saveDraft();
  if(a==='load-draft'){draft=loadConfig(KEYS.draft,published);markDirty();render();return toast('저장된 초안을 불러왔습니다.');}
  if(a==='publish')return publish();
  if(a==='preview-draft')return previewDraft();
  if(a==='preview-mobile'||a==='preview-full'){const iframe=overlay.querySelector('iframe');iframe.style.maxWidth=a==='preview-mobile'?'390px':'100%';iframe.style.margin='0 auto';return;}
  if(a==='add-banner'||a==='edit-banner')return bannerEditor(id);
  if(a==='toggle-banner')return mutate(()=>{const b=draft.banners.find(b=>b.id===id);b.enabled=!b.enabled;});
  if(a==='delete-banner')return mutate(()=>draft.banners=draft.banners.filter(b=>b.id!==id),'배너를 삭제했습니다. 저장 이력으로 복구할 수 있습니다.');
  if(a==='duplicate-banner')return mutate(()=>{const b=clone(draft.banners.find(b=>b.id===id));b.id='banner-'+Date.now();b.title+=' · 복제';draft.banners.push(b);},'배너를 복제했습니다.');
  if(a==='restore-history'){const h=history.find(h=>h.id===id);if(h){draft=validateConfig(h.config,catalog);markDirty();render();toast('선택한 구성을 초안으로 복구했습니다.');}return;}
  if(a==='export-config'){const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pinkrocket-main-config.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(a==='import-config')return app.querySelector('#config-file').click();
}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){event.preventDefault();Promise.resolve(action(target)).catch(error=>toast(error.message||'작업을 완료하지 못했습니다.'));}else if(event.target.matches('[data-dismiss]'))closeOverlay();});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='shop-search'){tabStates[tab].query=t.value;tabStates[tab].limit=8;renderFeed();}if(t.id==='admin-search'){adminQuery=t.value;adminLimit=60;renderAdminRows();}});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='shop-sort'){tabStates[tab].sort=t.value;tabStates[tab].limit=8;renderFeed();}if(t.id==='hide-soldout')mutate(()=>draft.tabs[adminTab].hideSoldout=t.checked);if(t.dataset.rowSelect){t.checked?selected.add(t.dataset.rowSelect):selected.delete(t.dataset.rowSelect);}if(t.hasAttribute('data-select-all')){app.querySelectorAll('[data-row-select]').forEach(c=>{c.checked=t.checked;t.checked?selected.add(c.dataset.rowSelect):selected.delete(c.dataset.rowSelect);});}if(t.dataset.rank){const value=Number(t.value),list=resolveList(catalog,adminTab,draft);if(Number.isInteger(value)&&value>=1&&value<=list.length)mutate(()=>reorder(draft,catalog,adminTab,t.dataset.rank,value-1));else{renderAdminRows();toast('목록 범위 안의 순번을 입력하세요.');}}if(t.id==='config-file'&&t.files[0]){try{if(t.files[0].size>1500000)throw Error('구성 파일은 1.5MB 이하여야 합니다.');draft=validateConfig(JSON.parse(await t.files[0].text()),catalog);markDirty();render();toast('구성을 초안으로 가져왔습니다.');}catch(error){toast(error.message);}}if(t.id==='banner-image-file'&&t.files[0]){const f=t.files[0];if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>800000){toast('PNG/JPEG/WebP 800KB 이하 파일을 선택하세요.');t.value='';return;}const reader=new FileReader();reader.onload=()=>{overlay.querySelector('[name="image"]').value=reader.result;toast('이미지를 준비했습니다. 배너 변경 적용을 눌러주세요.');};reader.readAsDataURL(f);}});
function syncFilterSheet(){const open=view==='shop'&&!!app.querySelector('.discovery[open]');document.body.classList.toggle('filters-open',open);if(open)document.body.style.overflow='hidden';else if(!overlay.children.length)document.body.style.overflow='';}
function setFiltersOpen(open){discoveryOpen=open;const details=app.querySelector('.discovery');if(!details)return;details.open=open;syncFilterSheet();if(open)app.querySelector('[aria-label="필터 닫기"]')?.focus();else details.querySelector('summary')?.focus();}
document.addEventListener('toggle',event=>{if(event.target.matches?.('.discovery')&&event.target.isConnected){discoveryOpen=event.target.open;syncFilterSheet();if(discoveryOpen&&!document.activeElement?.closest('.discovery-body'))app.querySelector('[aria-label="필터 닫기"]')?.focus();}},true);
document.addEventListener('keydown',event=>{if(!document.body.classList.contains('filters-open'))return;if(event.key==='Escape'){event.preventDefault();setFiltersOpen(false);}if(event.key==='Tab'){const items=[...app.querySelectorAll('.discovery-body button,.discovery-body input,.discovery-body select')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.addEventListener('input',event=>{if(['discovery-min','discovery-max'].includes(event.target.id)){const s=tabStates[tab];s.discovery[event.target.id==='discovery-min'?'min':'max']=event.target.value;s.limit=8;renderFeed();}});
document.addEventListener('change',event=>{
 const s=tabStates[tab];if(event.target.id==='discovery-strict'){s.discovery.strict=event.target.checked;s.limit=8;renderFeed();}
 if(event.target.id==='discovery-cap'){s.discovery.cap=Number(event.target.value);s.limit=8;renderFeed();}
 if(event.target.id==='discovery-photo'&&event.target.files[0])readDiscoveryPhoto(event.target.files[0]);
});
function readDiscoveryPhoto(file){
 if(!file.type.startsWith('image/'))return toast('이미지 파일을 선택해 주세요.');
 if(file.size>15000000)return toast('15MB 이하 사진을 선택해 주세요.');
 const targetTab=tab,token=++photoReadToken,reader=new FileReader();
 reader.onerror=()=>toast('사진을 읽지 못했습니다.');
 reader.onload=()=>{const img=new Image();img.onerror=()=>toast('이 사진 형식을 읽지 못했습니다.');img.onload=()=>{
  if(token!==photoReadToken||tab!==targetTab)return;
  try{const canvas=document.createElement('canvas');canvas.width=canvas.height=48;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,48,48);const pixels=ctx.getImageData(0,0,48,48).data;let sx=0,sy=0,weight=0;
  for(let i=0;i<pixels.length;i+=4){const r=pixels[i]/255,g=pixels[i+1]/255,b=pixels[i+2]/255,max=Math.max(r,g,b),min=Math.min(r,g,b),df=max-min;if(df<.12||pixels[i+3]<128)continue;const h=(max===r?((g-b)/df)%6:max===g?(b-r)/df+2:(r-g)/df+4)*Math.PI/3;sx+=Math.cos(h)*df;sy+=Math.sin(h)*df;weight+=df;}
  const d=tabStates[targetTab].discovery;d.photoTone={grey:weight<20,hue:(Math.atan2(sy,sx)*180/Math.PI+360)%360};d.photoPreview=reader.result;tabStates[targetTab].sort='match';tabStates[targetTab].limit=8;discoveryOpen=true;if(view==='shop')render();
  }catch{toast('사진의 색감을 읽지 못했습니다.');}
 };img.src=reader.result;};reader.readAsDataURL(file);
}
document.addEventListener('submit',event=>{if(event.target.id!=='banner-form')return;event.preventDefault();try{const form=event.target,data=new FormData(form),old=draft.banners.find(b=>b.id===form.dataset.bannerId),b={id:form.dataset.bannerId,type:data.get('type'),title:String(data.get('title')).trim(),subtitle:String(data.get('subtitle')),tag:String(data.get('tag')),after:Number(data.get('after')),span:Number(data.get('span')),tabs:data.getAll('tabs'),enabled:data.has('enabled'),tone:data.get('tone'),image:String(data.get('image')).trim(),link:String(data.get('link')).trim()};if(!b.tabs.length)throw Error('노출할 탭을 하나 이상 선택하세요.');const next=clone(draft);if(old)next.banners=next.banners.map(x=>x.id===b.id?b:x);else next.banners.push(b);draft=validateConfig(next,catalog);markDirty();closeOverlay();render();toast('배너를 초안에 적용했습니다.');}catch(error){toast(error.message);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&overlay.children.length)closeOverlay();if(event.key==='Tab'&&overlay.children.length){const elements=[...overlay.querySelectorAll('button:not(:disabled),a[href],input:not([type="file"]),select,textarea,iframe')].filter(e=>e.offsetParent!==null);if(!elements.length)return;const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
let pointer=null,suppressClick=false,clickTimer;
document.addEventListener('error',event=>{const img=event.target;if(img.classList?.contains('gesture-neighbor')){img.style.visibility='hidden';return;}if(img.tagName==='IMG'&&img.closest('.product-photo,.quickview-photo')){img.style.visibility='hidden';img.parentElement.classList.add('image-missing');}},true);
function resetSwipe(gesture=pointer){
  if(!gesture?.gallery)return;
  const gallery=gesture.gallery;
  gallery.classList.remove('swiping');gallery.querySelector('.gesture-neighbor')?.remove();gallery.querySelector('.swipe-cue')?.remove();
  const img=gallery.querySelector('.photo-link img');if(img){img.style.removeProperty('transform');img.style.removeProperty('transition');}
}
function blockDragClick(){clearTimeout(clickTimer);suppressClick=true;clickTimer=setTimeout(()=>suppressClick=false,250);}
function cancelSwipe(){resetSwipe();pointer=null;}
document.addEventListener('pointerdown',event=>{
  if(event.isPrimary===false){cancelSwipe();return;}
  cancelSwipe();suppressClick=false;
  if(event.button!==0||view!=='shop'||overlay.children.length||document.body.classList.contains('filters-open'))return;
  const target=event.target;
  if(target.closest('.labbar,input,select,textarea,[contenteditable="true"]'))return;
  const gallery=target.closest('[data-gallery]');
  pointer={id:gallery?.dataset.gallery,gallery,width:gallery?.getBoundingClientRect().width||240,pointerId:event.pointerId,x:event.clientX,y:event.clientY};
});
document.addEventListener('pointermove',event=>{
  if(!pointer||event.pointerId!==pointer.pointerId)return;
  const dx=event.clientX-pointer.x,dy=event.clientY-pointer.y;
  if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)*1.2){cancelSwipe();return;}
  if(!pointer.gallery||Math.abs(dx)<8||Math.abs(dx)<=Math.abs(dy)*1.5)return;
  const g=pointer.gallery,p=catalog.find(p=>p.id===pointer.id),delta=dx<0?1:-1;
  const intent=swipeIntent(dx,dy,{gallery:true,width:pointer.width,count:p.images.length});
  g.classList.add('swiping');const img=g.querySelector('.photo-link img');
  const offset=p.images.length>1?Math.max(-pointer.width*.92,Math.min(pointer.width*.92,dx)):Math.max(-20,Math.min(20,dx*.2));
  img.style.transition='none';img.style.transform=`translateX(${offset}px)`;
  if(p.images.length>1){
    let ghost=g.querySelector('.gesture-neighbor');if(!ghost){ghost=img.cloneNode(false);ghost.className='gesture-neighbor';ghost.loading='eager';ghost.alt='';ghost.setAttribute('aria-hidden','true');g.querySelector('.photo-link').appendChild(ghost);}
    const index=((photoState.get(p.id)||0)+delta+p.images.length)%p.images.length;
    if(ghost.getAttribute('src')!==p.images[index])ghost.src=p.images[index];
    ghost.style.transform=`translateX(${delta*pointer.width+offset}px)`;
  }
  let cue=g.querySelector('.swipe-cue');if(!cue){cue=document.createElement('span');cue.className='swipe-cue';cue.setAttribute('aria-hidden','true');g.appendChild(cue);}
  cue.textContent=p.images.length>1?'사진 넘기기':'등록된 사진 1장';
  
});
document.addEventListener('pointerup',event=>{
  if(!pointer||event.pointerId!==pointer.pointerId)return;
  const gesture=pointer;pointer=null;
  const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y,p=catalog.find(p=>p.id===gesture.id);
  resetSwipe(gesture);
  if(view!=='shop'||overlay.children.length)return;
  const intent=swipeIntent(dx,dy,{gallery:!!gesture.gallery,width:gesture.width,count:p?.images.length||1}),delta=dx<0?1:-1;
  if(intent==='photo'){
    slide(p.id,delta);
    const gallery=app.querySelector(`[data-gallery="${CSS.escape(p.id)}"]`);
    gallery.style.setProperty('--photo-arrive-from',`${delta*gesture.width+Math.max(-gesture.width*.92,Math.min(gesture.width*.92,dx))}px`);gallery.classList.add('photo-arrive');
    setTimeout(()=>gallery.classList.remove('photo-arrive'),200);
  }else if(intent==='tab')adjacentTab(delta);
  if(Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy)*1.5)blockDragClick();
});
document.addEventListener('pointercancel',cancelSwipe);
window.addEventListener('blur',cancelSwipe);
document.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopImmediatePropagation();suppressClick=false;}},true);
document.addEventListener('keydown',event=>{const tabButton=event.target.closest('.category-tabs [data-tab]');if(!tabButton||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?TABS[0]:event.key==='End'?TABS.at(-1):TABS[TABS.indexOf(tabButton.dataset.tab)+(event.key==='ArrowRight'?1:-1)];if(next){setTab(next);app.querySelector(`.category-tabs [data-tab="${next}"]`)?.focus();}});
function bindDrag(){let dragged=null;app.querySelectorAll('[data-row-id]').forEach(row=>{row.ondragstart=event=>{if(event.target.closest('input,button'))return event.preventDefault();dragged=row.dataset.rowId;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',dragged);};row.ondragover=event=>{event.preventDefault();row.classList.add('drag-over');};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=event=>{event.preventDefault();row.classList.remove('drag-over');if(!dragged)return;const items=resolveList(catalog,adminTab,draft),index=items.findIndex(p=>p.id===row.dataset.rowId);mutate(()=>reorder(draft,catalog,adminTab,dragged,index));};});}
window.addEventListener('storage',event=>{if(event.key===KEYS.published){published=removeStarterBanners(loadConfig(KEYS.published,published));if(view==='shop'&&!previewMode)render();}if(event.key===KEYS.favorites){favorites=read(KEYS.favorites,[]).filter(id=>catalog.some(p=>p.id===id));if(view==='shop')render();}if(event.key===KEYS.draft&&previewMode){draft=removeStarterBanners(loadConfig(KEYS.draft,draft));render();}});
async function registerBrowserTools(){const registry=document.modelContext;if(typeof registry?.registerTool!=='function')return;try{await registry.registerTool({name:'read_curation_state',description:'Read local mockup curation state. No real Makeshop account is connected.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({mode:'local-demo',tab:adminTab,dirty,visible:resolveList(catalog,adminTab,draft).map(p=>({id:p.id,name:p.name})),config:clone(draft)})});await registry.registerTool({name:'move_curation_product',description:'Move a product within this local demo draft only. Same action as the visible rank input.',inputSchema:{type:'object',properties:{tab:{type:'string',enum:TABS},id:{type:'string'},position:{type:'integer',minimum:1}},required:['tab','id','position'],additionalProperties:false},execute:async input=>{if(!input||!TABS.includes(input.tab)||typeof input.id!=='string'||!Number.isInteger(input.position))throw Error('Invalid input');const list=resolveList(catalog,input.tab,draft);if(!list.some(p=>p.id===input.id)||input.position<1||input.position>list.length)throw Error('Product or position not found');reorder(draft,catalog,input.tab,input.id,input.position-1);markDirty();render();return {updated:true,mode:'local-demo',order:resolveList(catalog,input.tab,draft).map(p=>p.id)};}});}catch(error){console.info('Optional browser tools unavailable:',error.message);}}
async function init(){try{const response=await fetch('./assets/catalog.json?v=5');if(!response.ok)throw Error('상품 파일을 불러오지 못했습니다.');catalog=normalizeCatalog(await response.json());if(!catalog.length)throw Error('상품 데이터가 비어 있습니다.');const base=initialConfig();published=removeStarterBanners(loadConfig(KEYS.published,base));draft=removeStarterBanners(loadConfig(KEYS.draft,published));write(KEYS.published,published);write(KEYS.draft,draft);history=read(KEYS.history,[]).map(h=>{try{return {...h,config:migrateSavedConfig(h.config,catalog)};}catch{return null;}}).filter(Boolean).slice(0,8);favorites=read(KEYS.favorites,[]).filter(id=>catalog.some(p=>p.id===id));cart=read(KEYS.cart,[]).filter(x=>catalog.some(p=>p.id===x.id)&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=99);const params=new URLSearchParams(location.search);view=params.get('view')==='admin'?'admin':'shop';previewMode=params.get('preview')==='1';frameMode=params.get('frame')==='1';tab=TABS.includes(params.get('tab'))?params.get('tab'):'추천';adminTab=tab;tabStates[tab].query=params.get('q')||'';tabStates[tab].material=MATERIALS.includes(params.get('material'))?params.get('material'):'전체';tabStates[tab].sort=['curated','match','newest','priceAsc','priceDesc'].includes(params.get('sort'))?params.get('sort'):'curated';markDirty();render();registerBrowserTools();}catch(error){app.innerHTML=`<main class="empty"><h1>화면을 준비하지 못했습니다.</h1><p>${esc(error.message)}</p><button class="btn" onclick="location.reload()">다시 시도</button></main>`;}}
init();
